        throw new IllegalArgumentException("Invalid date format");
    }
    int month = Integer.parseInt(parts[0]);
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    String[] monthNames = {
        "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"
    };

    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Month out of range");
    }

    java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
    java.time.DayOfWeek dow = localDate.getDayOfWeek();
    String weekday = dow.getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

    String monthName = monthNames[month - 1];
    return String.format("%s %d, %d is a %s", monthName, day, year, weekday);
}

