import java.util.*;

class Solution {

  /**
   * Given a tree with n nodes and edges, and a boolean array hasApple indicating if each node has an apple.
   * Starting from node 0, return the minimum time required to collect all the apples and return to node 0.
   *
   * Example:
   * Input: n = 7, edges = [[0,1],[0,2],[1,4],[1,5],[2,3],[2,6]], hasApple = [false,false,true,false,true,true,false]
   * Output: 8
   *
   * Input: n = 7, edges = [[0,1],[0,2],[1,4],[1,5],[2,3],[2,6]], hasApple = [false,false,true,false,false,true,false]
   * Output: 6
   *
   * Input: n = 7, edges = [[0,1],[0,2],[1,4],[1,5],[2,3],[2,6]], hasApple = [false,false,false,false,false,false,false]
   * Output: 0
   */
  List<Set<Integer>> tree;
  int[] res;

  public int minTime(int n, int[][] edges, boolean[] hasApple)

canonical_solution:
{
  tree = new ArrayList<>();
  res = new int[n];
  Arrays.fill(res, -1);
  for (int i = 0; i < n; ++i) tree.add(new HashSet<>());
  for (int[] e : edges) {
    tree.get(e[0]).add(e[1]);
    tree.get(e[1]).add(e[0]);
  }
  return dfs(hasApple, 0, -1);
}

int dfs(boolean[] hasApple, int node, int parent) {
  if (res[node] >= 0) return res[node];
  int total = 0;
  for (int child : tree.get(node)) {
    if (child == parent) continue;
    int childCost = dfs(hasApple, child, node);
    if (childCost > 0 || hasApple[child]) total += childCost + 2;
  }
  return res[node] = total;
}

