public int kthFactor(int n, int k) {
    int sqrt = (int)Math.sqrt(n);
    int countLower = 0;
    int[] large = new int[sqrt + 1];
    int largeSize = 0;
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            if (countLower + 1 == k) return i;
            countLower++;
            int other = n / i;
            if (other != i) {
                large[largeSize++] = other;
            }
        }
    }
    if (k <= countLower) return -1; // but already handled else?
    int remaining = k - countLower;
    if (remaining > largeSize) return -1;
    return large[largeSize - remaining];
}

